#include <bits/stdc++.h>
using namespace std;

#define rep(i, n) for(long long i = 0; i < n; ++i)
#define ll long long
#define Q 500010
#define K 20
#define LMAX (ll)1e+18

struct seg{
	long long idx;
	long long ofs;
};

ll len[Q];
seg lgt[Q];
seg hev[Q][K];

void init(void){
	rep(i,Q){
		len[i]=-1;
		lgt[i]={-1,-1};
		rep(j,K)hev[i][j]={-1,-1};
	}
	len[0]=1,len[1]=1;
	return;
}

void concat_seg(long long nidx, long long le,long long ri){
	ll nlen=len[le]+len[ri];
	if(nlen>LMAX)nlen=LMAX;
	len[nidx]=nlen;
	ll llen=len[le];
	ll rlen=nlen-llen;
	if(llen<rlen){
		lgt[nidx]={le,0};
		hev[nidx][0]={ri,llen};
		long long cur=ri;
		ll curofs=llen;
		for(long long i=1;i<K;i++){
			curofs+=hev[cur][i-1].ofs;
			cur=hev[cur][i-1].idx;
			if(cur==-1)break;
			if(curofs>LMAX)break;
			hev[nidx][i]={cur,curofs};
		}
	}
	else{
		lgt[nidx]={ri,llen};
		hev[nidx][0]={le,0};
		long long cur=le;
		ll curofs=0;
		for(long long i=1;i<K;i++){
			curofs+=hev[cur][i-1].ofs;
			cur=hev[cur][i-1].idx;
			if(cur==-1)break;
			if(curofs>LMAX)break;
			hev[nidx][i]={cur,curofs};
		}
	}
	return;
}

long long search(long long k,long long x){
	if(k<=1)return k;
	long long curk=k, curx=x;
	for(long long i=19;i>=0;i--){
		if(hev[curk][i].idx==-1)continue;
		if((hev[curk][i].ofs<=curx)&&(curx<(hev[curk][i].ofs+len[hev[curk][i].idx]))){
			curx-=hev[curk][i].ofs;
			curk=hev[curk][i].idx;
		}
	}
	while(lgt[curk].idx!=-1){
		if((lgt[curk].ofs<=curx)&&(curx<(lgt[curk].ofs+len[lgt[curk].idx]))){
			curx-=lgt[curk].ofs;
			curk=lgt[curk].idx;
		}
		else break;
	}
	return search(curk,curx);
}



int main() {
	long long q,le,ri,x;
	init();
	cin>>q;
	rep(qq,q){
		cin>>le>>ri>>x;
		concat_seg(qq+2,le,ri);
		cout<<search(qq+2,x-1)<<endl;
	}

	return 0;
}
